// T90: the host's C64 key matrix (keys[col*8+row], 1 = down) into the C264 matrix (k264[col*8+row], 1 = down). Generated by
// cores/c264/sim/keymap.py from the two keyboards' key names; do not edit by hand. Written for this project.
// Positional: the C64 keys with the same legend map to the same key; F1/F3/F5/F7 -> F1/F2/F3/HELP; back-arrow -> ESC;
// CRSR down/right with SHIFT -> UP/LEFT (SHIFT is removed from the C264 matrix then); up-arrow and RESTORE have no C264 key.
`timescale 1ns / 1ps
module c264_keys (
    input  wire [63:0] keys,
    output wire [63:0] k264
);
    wire shift = keys[15] | keys[52];
    wire cur_d = keys[7];
    wire cur_r = keys[2];
    assign k264[0] = keys[0];   // DEL
    assign k264[1] = keys[8];   // 3
    assign k264[2] = keys[16];   // 5
    assign k264[3] = keys[24];   // 7
    assign k264[4] = keys[32];   // 9
    assign k264[5] = cur_d & ~shift;   // DOWN
    assign k264[6] = cur_r & shift;   // LEFT
    assign k264[7] = keys[56];   // 1
    assign k264[8] = keys[1];   // RETURN
    assign k264[9] = keys[9];   // W
    assign k264[10] = keys[17];   // R
    assign k264[11] = keys[25];   // Y
    assign k264[12] = keys[33];   // I
    assign k264[13] = keys[41];   // P
    assign k264[14] = keys[49];   // *
    assign k264[15] = keys[51];   // HOME
    assign k264[16] = keys[48];   // POUND
    assign k264[17] = keys[10];   // A
    assign k264[18] = keys[18];   // D
    assign k264[19] = keys[26];   // G
    assign k264[20] = keys[34];   // J
    assign k264[21] = keys[42];   // L
    assign k264[22] = keys[50];   // ;
    assign k264[23] = keys[58];   // CTRL
    assign k264[24] = keys[3];   // HELP
    assign k264[25] = keys[11];   // 4
    assign k264[26] = keys[19];   // 6
    assign k264[27] = keys[27];   // 8
    assign k264[28] = keys[35];   // 0
    assign k264[29] = cur_d & shift;   // UP
    assign k264[30] = cur_r & ~shift;   // RIGHT
    assign k264[31] = keys[59];   // 2
    assign k264[32] = keys[4];   // F1
    assign k264[33] = keys[12];   // Z
    assign k264[34] = keys[20];   // C
    assign k264[35] = keys[28];   // B
    assign k264[36] = keys[36];   // M
    assign k264[37] = keys[44];   // .
    assign k264[38] = keys[57];   // ESC
    assign k264[39] = keys[60];   // SPACE
    assign k264[40] = keys[5];   // F2
    assign k264[41] = keys[13];   // S
    assign k264[42] = keys[21];   // F
    assign k264[43] = keys[29];   // H
    assign k264[44] = keys[37];   // K
    assign k264[45] = keys[45];   // :
    assign k264[46] = keys[53];   // =
    assign k264[47] = keys[61];   // C=
    assign k264[48] = keys[6];   // F3
    assign k264[49] = keys[14];   // E
    assign k264[50] = keys[22];   // T
    assign k264[51] = keys[30];   // U
    assign k264[52] = keys[38];   // O
    assign k264[53] = keys[43];   // -
    assign k264[54] = keys[40];   // +
    assign k264[55] = keys[62];   // Q
    assign k264[56] = keys[46];   // @
    assign k264[57] = shift & ~cur_d & ~cur_r;   // SHIFT
    assign k264[58] = keys[23];   // X
    assign k264[59] = keys[31];   // V
    assign k264[60] = keys[39];   // N
    assign k264[61] = keys[47];   // ,
    assign k264[62] = keys[55];   // /
    assign k264[63] = keys[63];   // STOP
endmodule
